import { bech32Encode, bech32Decode } from './bech32Core.mjs';

// Package-level segwit encode/decode, mirroring the Python `bech32` package
// (old BIP-173 reference style). The witness program is handled as raw 5-bit
// values end to end: encode does NOT call convertbits, and decode returns
// 5-bit values directly, NOT bytes. Checksum constant is 1 everywhere
// (old bech32, no bech32m).

export function decode(hrp, addr) {
  const [hrpgot, data] = bech32Decode(addr);
  if (hrpgot !== hrp) {
    return [null, null];
  }
  if (data[0] > 16) {
    return [null, null];
  }
  const m = data.length - 1;
  if (m < 2 || m > 40) {
    return [null, null];
  }
  if (data[0] === 0 && m !== 32 && m !== 52) {
    return [null, null];
  }
  return [data[0], data.slice(1)];
}

export function encode(hrp, witver, witprog) {
  const ret = bech32Encode(hrp, [witver, ...witprog]);
  const [v, p] = decode(hrp, ret);
  if (v === null && p === null) {
    return null;
  }
  return ret;
}

