import { CHARSET } from '/output/lib/charset.mjs';
import { convertbits } from '/output/lib/convertbits.mjs';
import assert from 'node:assert/strict';

assert.equal(CHARSET, 'qpzry9x8gf2tvdw0s3jn54khce6mua7l');

assert.deepEqual(convertbits([215,213,235,231,227,198,237,186,172,166,204,68,105,125,111,97,99,186,237,209], 8, 5),
  [26,31,10,30,23,25,31,3,24,27,22,27,21,11,5,6,25,17,2,6,18,31,11,15,12,5,17,27,21,27,14,17]);
