assert.deepEqual(convertbits([0,28], 5, 8, false), [7]);
// pad default is true
assert.deepEqual(convertbits([0,28], 5, 8), [7,0]);
// negative value rejected
assert.equal(convertbits([-1,2], 8, 5), null);
console.log('all convertbits/charset self-tests passed');
"

