// Stub mirroring the fixed contract: decode lowercases, throws on null.
export function bech32Encode(hrp, data) {
  return hrp + '1' + data.map((d) => String(d)).join('');
}
export function bech32Decode(bech) {
  if (bech === null) throw new TypeError('null');
  const lower = bech.toLowerCase();
  const i = lower.indexOf('1');
  const hrp = lower.slice(0, i);
  const data = lower.slice(i + 1).split('').map((c) => {
