import { encode, decode } from "/tmp/segwitTest/lib/segwitAddr.mjs";
const assert = (cond, msg) => { if (!cond) throw new Error("FAIL: " + msg); };

// v1, 25 five-bit values (m=25? no: data.length-1) — use m=40 (witver=1, 40 prog values)
assert(encode("tb", 1, Array(40).fill(0)) !== null, "v1 m=40 should encode");
// v1 m=42 fails
assert(encode("tb", 1, Array(42).fill(0)) === null, "v1 m=42 should be null");
// v0 m=32 works
assert(encode("tb", 0, Array(32).fill(0)) !== null, "v0 m=32 should encode");
// v0 m=52 fails (m > 40)
assert(encode("tb", 0, Array(52).fill(0)) === null, "v0 m=52 should be null");
// v0 other lengths fail
assert(encode("tb", 0, Array(20).fill(0)) === null, "v0 m=20 should be null");
// witver 17 fails roundtrip
assert(encode("tb", 17, Array(32).fill(0)) === null, "witver 17 should be null");
// uppercase HRP fails roundtrip (decode lowercases)
assert(encode("TB", 1, Array(40).fill(0)) === null, "uppercase HRP should be null");
// null witprog throws TypeError
let threw = false;
try { encode("tb", 1, null); } catch (e) { threw = e instanceof TypeError; }
assert(threw, "null witprog should throw TypeError");
// decode: null addr throws TypeError
threw = false;
try { decode("tb", null); } catch (e) { threw = e instanceof TypeError; }
assert(threw, "null addr should throw TypeError");
// decode hrp mismatch
assert(decode("bc", "tb1" + "0".repeat(33))[0] === null, "hrp mismatch -> [null,null]");
// decode roundtrip returns 5-bit values
const [v, p] = decode("tb", "tb1" + "1" + "2".repeat(40));
assert(v === 1 && p.length === 40 && p.every((x) => x === 2), "decode returns witver + 5-bit prog");
// data[0] > 16
assert(decode("tb", "tb1" + "9".repeat(41))[0] === null, "witver > 16 -> null (9? no, 9<=16)");
// m < 2
assert(decode("tb", "tb1" + "12")[0] === null, "m=1 -> null");
console.log("ALL_TESTS_PASSED");
'

