// Minimal replica of the Python argparse behavior used by the original script:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=int, required=True)
//   parser.add_argument('--c', type=str, required=True)

import { basename } from 'node:path';

const OPTIONS = ['--a', '--b', '--c']; // declaration order (used in error messages)

// argparse's _negative_number_matcher; since none of our option strings look
// like negative numbers, tokens matching this are treated as values.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function prog() {
  const argv1 = process.argv[1];
  return argv1 ? basename(argv1) : 'test16.mjs';
}

function usageLine() {
  return `usage: ${prog()} [-h] --a A --b B --c C`;
}

function errorExit(message) {
  process.stderr.write(usageLine() + '\n');
  process.stderr.write(`${prog()}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  const lines = [
    usageLine(),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function isOptionLike(token) {
  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token);
}

// Strict Python int() semantics: trim surrounding whitespace, then an
// optional sign followed by base-10 digits only (int('0x10') fails in Python).
// Returns a Number, or null on invalid literal.
function strictInt(value) {
  const t = value.trim();
  if (!/^[+-]?\d+$/.test(t)) return null;
  return parseInt(t, 10);
}

export function parseArgs() {
  const argv = process.argv.slice(2);
  const values = { a: undefined, b: undefined, c: undefined };
  const seen = new Set();
  const extras = [];
  let noMoreOptions = false;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (!noMoreOptions && token === '--') {
      noMoreOptions = true;
      i += 1;
      continue;
    }

    if (!noMoreOptions && isOptionLike(token)) {
      let name = token;
      let inlineValue;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      if (name === '-h' || name === '--help') {
        printHelp();
        process.exit(0);
      }

      if (!OPTIONS.includes(name)) {
        extras.push(token);
        i += 1;
        continue;
      }

      let value;
      if (inlineValue !== undefined) {
        value = inlineValue;
        i += 1;
      } else {
        if (i + 1 >= argv.length || isOptionLike(argv[i + 1])) {
          errorExit(`argument ${name}: expected one argument`);
        }
        value = argv[i + 1];
        i += 2;
      }

      seen.add(name); // last occurrence wins
      if (name === '--b') {
        const parsed = strictInt(value);
        if (parsed === null) {
          errorExit(`argument --b: invalid int value: '${value}'`);
        }
        values.b = parsed;
      } else if (name === '--a') {
        values.a = value;
      } else {
        values.c = value;
      }
    } else {
      extras.push(token);
      i += 1;
    }
  }

  const missing = OPTIONS.filter((opt) => !seen.has(opt));
  if (missing.length > 0) {
    errorExit(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

