import { parseArgs } from './lib/argparse.mjs';
import { convertbits } from './lib/convertbits.mjs';
import { encode, decode } from './lib/segwitAddr.mjs';
import { pyList } from './lib/pyprint.mjs';

// Strict Python int() semantics: trim surrounding whitespace, then an
// optional sign followed by base-10 digits only. On an invalid literal,
// mirror Python's uncaught ValueError (stderr message, exit code 1,
// stdout stays empty).
function pyInt(value) {
  const t = value.trim();
  if (!/^[+-]?\d+$/.test(t)) {
    throw new Error(`ValueError: invalid literal for int() with base 10: '${value}'`);
  }
  return parseInt(t, 10);
}

function main() {
  const args = parseArgs();
  const data = args.c.split(',').map(pyInt);
  const converted = convertbits(data, 8, 5);
  // If converted is null, encode throws (spread of null) — left uncaught
  // on purpose, exactly like the Python original.
  const encoded = encode(args.a, args.b, converted);
  // If encoded is null, decode throws TypeError — also left uncaught.
  const decoded = decode(args.a, encoded);
  if (decoded[0] !== null && decoded[1] !== null) {
    const [witver, witprog] = decoded;
    const convertedBack = convertbits(witprog, 5, 8);
    console.log(pyList(converted));
    console.log(encoded);
    console.log(witver);
    console.log(pyList(convertedBack));
  }
}

main();

