import { convertbits } from './convertbits.mjs';

// Package-level segwit encode/decode, mirroring the Python `bech32` package
// (old BIP-173 reference style). encode converts the witness program from
// 8-bit to 5-bit with convertbits, and decode converts it back to 8-bit
// bytes. Checksum constant is 1 everywhere (old bech32, no bech32m).

export function decode(hrp, addr) {
  const [hrpgot, data] = bech32Decode(addr);
  if (hrpgot !== hrp) {
    return [null, null];
  }
  const decoded = convertbits(data.slice(1), 5, 8, false);
  if (decoded === null || decoded.length < 2 || decoded.length > 40) {
    return [null, null];
  }
  if (data[0] > 16) {
    return [null, null];
  }
  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return [null, null];
  }
  return [data[0], decoded];
}

export function encode(hrp, witver, witprog) {
  const ret = bech32Encode(hrp, [witver, ...convertbits(witprog, 8, 5)]);
  const [v, p] = decode(hrp, ret);
  if (v === null && p === null) {
    return null;
  }
  return ret;
}

